import numpy as np
from scipy import ndimage as nd
from scipy.spatial import cKDTree
from PIL import Image,ImageDraw
MM=.22186

def contours(mask):
    # Trace oriented pixel edges, joining into simple closed contours.
    edge={}
    for y,x in zip(*np.where(mask)):
        if y==0 or not mask[y-1,x]:edge[(x,y)]=(x+1,y)
        if x==mask.shape[1]-1 or not mask[y,x+1]:edge[(x+1,y)]=(x+1,y+1)
        if y==mask.shape[0]-1 or not mask[y+1,x]:edge[(x+1,y+1)]=(x,y+1)
        if x==0 or not mask[y,x-1]:edge[(x,y+1)]=(x,y)
    loops=[]
    while edge:
        start=next(iter(edge));p=start;arr=[]
        while p in edge:
            arr.append(p);p=edge.pop(p)
            if p==start:break
        if len(arr)>8:
            a=np.array(arr,dtype=float)-.5
            a=nd.gaussian_filter1d(a,1.5,axis=0,mode='wrap')
            loops.append(a)
    return loops

def make_path(mask,radius_mm=.7,spacing_mm=.95):
    d=nd.distance_transform_edt(mask)*MM
    loops=[]
    for offset in np.arange(radius_mm,d.max(),spacing_mm):
        loops.extend(contours(d>=offset))
    # Nested loops, join at nearest point. All four targets have ample internal connectivity.
    path=loops.pop(0);path=np.r_[path,path[:1]]
    while loops:
        best=None
        for j,L in enumerate(loops):
            dist,idx=cKDTree(path).query(L)
            q=int(np.argmin(dist));entry=(dist[q],j,q,int(idx[q]))
            if best is None or entry[0]<best[0]:best=entry
        _,j,q,k=best;L=loops.pop(j);L=np.roll(L,-q,axis=0);L=np.r_[L,L[:1]]
        # insert a closed excursion then continue the previous loop
        path=np.r_[path[:k+1],L,path[k:k+1],path[k+1:]]
    return path

if __name__=='__main__':
    b=np.array(Image.open('/app/target.png'))[:,:,0]<100
    labels,n=nd.label(b)
    for i in range(1,n+1):
        p=make_path(labels==i)
        np.save(f'/app/output/path{i}.npy',p)
        print(i,len(p),np.linalg.norm(np.diff(p,axis=0),axis=1).sum()*MM,'mm')
    im=Image.open('/app/target.png').convert('RGB');draw=ImageDraw.Draw(im)
    for i in range(1,n+1):
        p=np.load(f'/app/output/path{i}.npy')
        draw.line([tuple(v) for v in p],fill=(240,70,70),width=1)
    im.save('/app/output/path_preview.png')
